import { AuthorizationDetailsForm } from "@/components/oauth-consent-form";
type Props = {
  searchParams: Promise<{
    authorization_id?: string;
  }>;
};

export default function ConsentPage({ searchParams }: Props) {
  return (
    <div className="flex min-h-svh w-full items-center justify-center p-6 md:p-10">
      <div className="w-full max-w-sm">
        <AuthorizationDetailsForm
          authorizationId={searchParams.then((params) => {
            if (!params.authorization_id) {
              throw new Error("Authorization ID is required");
            }

            return params.authorization_id;
          })}
        />
      </div>
    </div>
  );
}

import { Suspense } from "react";
import { Card } from "@/components/ui/card";
import { ConsentHeader } from "./components/consent-header";
import { ConsentDetails } from "./components/consent-details";
import { ConsentDecision } from "./components/consent-decision";
import { ConsentShell } from "./components/consent-shell";

import { AuthorizationErrorBoundary } from "./components/error-boundary";
import { isAuthSessionMissingError } from "@supabase/supabase-js";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";

type Props = {
  authorizationId: Promise<string>;
};

export function AuthorizationDetailsForm({ authorizationId }: Props) {
  return (
    <AuthorizationErrorBoundary>
      <Suspense
        fallback={
          <ConsentShell>
            <p>Loading authorization request...</p>
          </ConsentShell>
        }
      >
        <AuthorizationDetails authorizationId={authorizationId} />
      </Suspense>
    </AuthorizationErrorBoundary>
  );
}

async function AuthorizationDetails({ authorizationId }: Props) {
  const details = await getAuthorizationDetails(await authorizationId);

  return (
    <Card>
      <ConsentHeader productName="My App" clientName={details.client.name} />
      <ConsentDetails details={details} />
      <ConsentDecision authorizationId={details.authorization_id} />
    </Card>
  );
}

async function getAuthorizationDetails(authorizationId: string) {
  const supabase = await createClient();
  const { data, error } =
    await supabase.auth.oauth.getAuthorizationDetails(authorizationId);

  if (error) {
    if (isAuthSessionMissingError(error)) {
      redirect(
        withSearchParams("/auth/login", {
          next: getConsentUrl(authorizationId),
        }),
      );
    }

    throw error;
  }

  if (!("authorization_id" in data)) {
    redirect(data.redirect_url);
  }

  return data;
}

function getConsentUrl(authorization_id: string) {
  return withSearchParams("/oauth/consent", { authorization_id });
}

const withSearchParams = (path: string, params: Record<string, string>) => {
  const searchParams = new URLSearchParams(Object.entries(params));
  const queryString = searchParams.toString();
  return `${path}?${queryString}`;
};

"use server";

import { createClient } from "@/lib/supabase/server";
import { redirect } from "next/navigation";
export type ConsentState = {
  error?: string;
} | null;

export async function decideConsent(
  _state: ConsentState,
  formData: FormData,
): Promise<ConsentState> {
  const authorizationId = String(formData.get("authorizationId") ?? "");
  const decision = formData.get("action");

  const supabase = await createClient();
  const { data: userData } = await supabase.auth.getUser();
  if (!userData.user) {
    return { error: "You must be signed in to continue." };
  }

  const { data, error } =
    decision === "approve"
      ? await supabase.auth.oauth.approveAuthorization(authorizationId, {
          skipBrowserRedirect: true,
        })
      : await supabase.auth.oauth.denyAuthorization(authorizationId, {
          skipBrowserRedirect: true,
        });

  if (error) {
    return { error: error.message };
  }

  if (!data.redirect_url) {
    return {
      error:
        "The server did not return a redirect. Start again from your OAuth client.",
    };
  }

  redirect(data.redirect_url);
}

"use client";

import { useActionState } from "react";
import { useFormStatus } from "react-dom";
import { Button } from "@/components/ui/button";
import { decideConsent } from "../action";
import { CardFooter } from "@/components/ui/card";

export function ConsentDecision({
  authorizationId,
}: {
  authorizationId: string;
}) {
  const [state, formAction, isPending] = useActionState(decideConsent, null);

  return (
    <CardFooter className="flex w-full flex-col gap-3">
      {state?.error && (
        <p role="alert" className="text-sm text-destructive">
          {state.error}
        </p>
      )}
      <div className="flex w-full flex-col-reverse gap-2 sm:flex-row sm:justify-end">
        <form action={formAction}>
          <input type="hidden" name="authorizationId" value={authorizationId} />
          <input type="hidden" name="action" value="deny" />
          <SubmitButton
            label="Deny"
            pendingLabel="Denying..."
            variant="outline"
            disabled={isPending}
          />
        </form>
        <form action={formAction}>
          <input type="hidden" name="authorizationId" value={authorizationId} />
          <input type="hidden" name="action" value="approve" />
          <SubmitButton
            label="Allow access"
            pendingLabel="Allowing..."
            variant="default"
            disabled={isPending}
          />
        </form>
      </div>
    </CardFooter>
  );
}

export function SubmitButton({
  label,
  pendingLabel,
  variant,
  disabled,
}: {
  label: string;
  pendingLabel: string;
  variant: "default" | "outline";
  disabled: boolean;
}) {
  const { pending } = useFormStatus();

  return (
    <Button type="submit" size="sm" variant={variant} disabled={disabled}>
      {pending ? pendingLabel : label}
    </Button>
  );
}

import { PropsWithChildren } from "react";
import type { OAuthAuthorizationDetails } from "@supabase/supabase-js";
import { CardContent } from "@/components/ui/card";

export function ConsentDetails({
  details,
}: {
  details: OAuthAuthorizationDetails;
}) {
  return (
    <CardContent className="space-y-6">
      <DetailsList>
        <DetailsItem>
          <DetailsLabel>Client</DetailsLabel>
          <DetailsValue>
            <span>{details.client.name}</span>
          </DetailsValue>
        </DetailsItem>
        <DetailsItem>
          <DetailsLabel>Redirects to</DetailsLabel>
          <DetailsValue>
            <span>{details.redirect_uri}</span>
          </DetailsValue>
        </DetailsItem>
        <DetailsItem>
          <DetailsLabel>Signed in as</DetailsLabel>
          <DetailsValue>
            <span>{details.user.email}</span>
          </DetailsValue>
        </DetailsItem>
        <DetailsItem>
          <DetailsLabel>Scopes</DetailsLabel>
          <DetailsValue>
            <span>{details.scope.split(" ").join(", ")}</span>
          </DetailsValue>
        </DetailsItem>
      </DetailsList>
      <p className="text-muted-foreground text-sm">
        Allow access only if you recognize this application. It can act on your
        behalf only within the requested permissions and the access you already
        have.
      </p>
    </CardContent>
  );
}

function DetailsList({ children }: PropsWithChildren) {
  return <dl className="divide-y rounded-lg border text-sm">{children}</dl>;
}

function DetailsItem({ children }: PropsWithChildren) {
  return (
    <div className="flex items-center justify-between gap-6 p-4">
      {children}
    </div>
  );
}

function DetailsLabel({ children }: PropsWithChildren) {
  return <dt className="text-muted-foreground">{children}</dt>;
}

function DetailsValue({ children }: PropsWithChildren) {
  return (
    <dd className="min-w-0 break-all text-right font-medium">{children}</dd>
  );
}

import { CardDescription, CardHeader, CardTitle } from "@/components/ui/card";

const getInitial = (value: string) =>
  value.trim().charAt(0).toUpperCase() || "?";

export function ConsentHeader({
  clientName,
  productName,
}: {
  productName: string;
  clientName: string;
}) {
  return (
    <CardHeader className="items-center space-y-4 text-center">
      <div className="flex items-center justify-center">
        <div className="flex size-12 items-center justify-center rounded-full border bg-muted font-medium">
          {getInitial(clientName)}
        </div>
        <div className="h-px w-8 bg-border" aria-hidden="true" />
        <div className="flex size-12 items-center justify-center rounded-full border bg-muted font-medium">
          {getInitial(productName)}
        </div>
      </div>
      <div className="space-y-1.5">
        <CardTitle className="font-medium text-lg tracking-normal">
          Authorize {clientName}
        </CardTitle>
        <CardDescription>
          Review what this client gets access to.
        </CardDescription>
      </div>
    </CardHeader>
  );
}

import { Card, CardContent } from "@/components/ui/card";
import { ConsentHeader } from "./consent-header";

export function ConsentShell({ children }: { children: React.ReactNode }) {
  return (
    <Card>
      <ConsentHeader clientName="OAuth Client" productName="My App" />
      <CardContent>{children}</CardContent>
    </Card>
  );
}

"use client";

import { catchError } from "next/error";
import { ConsentShell } from "./consent-shell";

export const AuthorizationErrorBoundary = catchError(function () {
  return (
    <ConsentShell>
      <p role="alert" className="text-sm text-destructive">
        Unable to load the authorization request. Start again from your OAuth
        client.
      </p>
    </ConsentShell>
  );
});
